mapper.select:
select info.ISSUE_PARTY_ID, case when length(PROD_NAME)>180 then substring(PROD_NAME,1,180) else PROD_NAME end ACCOUNT_NAME, VDATE, INFO.PROD_ID ACCOUNT_ID, NOW() STATUS_DATE, info.STATUS, info.CREATE_USER, info.UPDATE_USER, info.ORG_CODE, info.DEPT_CODE CREATE_DEPT from chb_prd_baseinfo info LEFT JOIN ( select ifnull(DEAL.FPROD_ID,DEAL.PROD_ID) PROD_ID, max(UPDATE_TIME) UPDATE_TIME,max(CREATE_TIME) CREATE_TIME from CHB_PRD_DEAL deal where trade_type = '01' and status IN ('E','M') group by ifnull(DEAL.FPROD_ID,DEAL.PROD_ID)
) DEAL ON INFO.PROD_ID = deal.PROD_ID
where DATE_FORMAT(greatest(ifnull(ifnull(info.UPDATE_TIME, info.CREATE_TIME), STR_TO_DATE('1900-01-01','%Y-%m-%d')), ifnull(info.VDATE,STR_TO_DATE('1900-01-01','%Y-%m-%d')), ifnull(ifnull(DEAL.UPDATE_TIME, DEAL.CREATE_TIME), STR_TO_DATE('1900-01-01','%Y-%m-%d'))),'%Y-%m-%d') = DATE_FORMAT(#{statusDate,jdbcType=DATE},'%Y-%m-%d') and deal.PROD_ID is not null and info.PROFIT_TYPE='03' and info.fprod_id is null and info.ISSUING_STATUS='01'
and info.prod_id in
