            #{item,jdbcType=VARCHAR}



        and t1.SUBMIT_FEEDBACK_STATUS in

            #{item,jdbcType=VARCHAR}



        and DATE_FORMAT(STATUS_DATE,'%Y-%m-%d') >= #{statusDateStart}


        and DATE_FORMAT(STATUS_DATE,'%Y-%m-%d') <= #{statusDateEnd}


        and DATE_FORMAT(SUBMIT_TIME,'%Y-%m-%d') >= #{submitTimeStart}


