mapper.insert:
insert into PBC_PRD_ACCOUNT_SUB_HIS () select REGIST_SEQNO, PBC_ACCOUNT_ID, ISSUE_PARTY_ID, ACCOUNT_ID,ACCOUNT_NAME, VDATE, SEND_STATUS, SUBMIT_TIME, SUBMIT_FEEDBACK_STATUS, SUMIT_SEQ, STATUS_DATE, PBC_SUBMIT_DEADLINE, SUBMIT_DEADLINE, STATUS, CREATE_USER, ORG_CODE, CREATE_DEPT, NOW(), UPDATE_USER, NOW() from PBC_PRD_ACCOUNT_SUB where PBC_ACCOUNT_ID in
#{item.pbcAccountId,jdbcType=CHAR}
and SEND_STATUS in ('02','03')

insert into PBC_PRD_ACCOUNT_SUB () select HIS_NO, PBC_ACCOUNT_ID, ISSUE_PARTY_ID, ACCOUNT_ID,ACCOUNT_NAME, VDATE, SEND_STATUS, SUBMIT_TIME, SUBMIT_FEEDBACK_STATUS, SUMIT_SEQ, STATUS_DATE, PBC_SUBMIT_DEADLINE, SUBMIT_DEADLINE, STATUS, CREATE_USER, ORG_CODE, CREATE_DEPT, NOW(), UPDATE_USER, NOW() from ( select , rank() over (partition by PBC_ACCOUNT_ID order by ifnull(update_time,create_time) desc) ranknum from PBC_PRD_ACCOUNT_SUB_HIS where PBC_ACCOUNT_ID in
#{item.pbcAccountId,jdbcType=CHAR}
)AS T where ranknum = 1

mapper.delete:
delete from PBC_PRD_ACCOUNT_SUB_HIS
where PBC_ACCOUNT_ID in (
select  PBC_ACCOUNT_ID
from (
select PBC_ACCOUNT_ID ,
rank() over (partition by PBC_ACCOUNT_ID order by ifnull(update_time,create_time) desc) ranknum
from PBC_PRD_ACCOUNT_SUB_HIS
where
PBC_ACCOUNT_ID in

    #{item.pbcAccountId,jdbcType=CHAR}

)AS T
where  ranknum = 1
)

mapper.select:
select PBC_ACCOUNT_ID, ACCOUNT_NAME from ( select PBC_ACCOUNT_ID,ACCOUNT_NAME, rank() over (partition by PBC_ACCOUNT_ID order by ifnull(update_time,create_time) desc) ranknum from PBC_PRD_ACCOUNT_SUB where STATUS != 'D'
AND PBC_ACCOUNT_ID LIKE concat_ws('','%', #{search},'%')
) tmp where ranknum = 1

select INSIDE_PROD_ID from ( select INSIDE_PROD_ID, rank() over (partition by INSIDE_PROD_ID order by ifnull(update_time,create_time) desc) ranknum from PBC_PROD_ASSETPOOL_CODE where STATUS != 'D'
AND INSIDE_PROD_ID LIKE concat('%', #{search},'%')
)tmp where ranknum = 1
